pub(super) const MIGRATION_V28: &str = r#"
CREATE TABLE provider_credential_v28_admission_guard (allowed INTEGER NOT NULL CHECK(allowed = 1));
INSERT INTO provider_credential_v28_admission_guard (allowed) SELECT CASE WHEN EXISTS (SELECT 1 FROM provider_credential_operations WHERE state NOT IN ('FAILED', 'EXPIRED', 'CANCELLED', 'TOMBSTONED') OR claimed_ticket_attempt IS NOT NULL) THEN 0 ELSE 1 END;
DROP TABLE provider_credential_v28_admission_guard;
ALTER TABLE provider_credential_operations ADD COLUMN qualified_release_tuple_digest BLOB CHECK(qualified_release_tuple_digest IS NULL OR length(qualified_release_tuple_digest) = 32);
CREATE TABLE provider_credential_completion_receipts (operation_id BLOB PRIMARY KEY NOT NULL REFERENCES provider_credential_operations(operation_id), installation_owner_id BLOB NOT NULL CHECK(length(installation_owner_id) = 32), provider_id TEXT NOT NULL, action TEXT NOT NULL, target_credential_version INTEGER, target_ref_digest BLOB, predecessor_lifecycle_revision INTEGER NOT NULL CHECK(predecessor_lifecycle_revision > 0), predecessor_credential_fence INTEGER NOT NULL CHECK(predecessor_credential_fence > 0), claimed_ticket_attempt INTEGER NOT NULL CHECK(claimed_ticket_attempt > 0), broker_migration_binding_digest BLOB CHECK(broker_migration_binding_digest IS NULL OR length(broker_migration_binding_digest) = 32), qualified_release_tuple_digest BLOB NOT NULL CHECK(length(qualified_release_tuple_digest) = 32 AND qualified_release_tuple_digest != zeroblob(32)), readback_disposition TEXT NOT NULL CHECK(readback_disposition IN ('EXACT_VERSION', 'EXACT_ABSENCE')), readback_observation_digest BLOB NOT NULL CHECK(length(readback_observation_digest) = 32), readiness_observation_id BLOB CHECK(readiness_observation_id IS NULL OR length(readiness_observation_id) = 16), successor_lifecycle_revision INTEGER NOT NULL CHECK(successor_lifecycle_revision > 0), successor_credential_fence INTEGER NOT NULL CHECK(successor_credential_fence > 0), successor_readiness_revision INTEGER NOT NULL CHECK(successor_readiness_revision > 0), active_credential_version INTEGER, active_ref_digest BLOB, next_credential_version INTEGER NOT NULL CHECK(next_credential_version > 0), CHECK((target_credential_version IS NULL AND target_ref_digest IS NULL) OR (target_credential_version > 0 AND length(target_ref_digest) = 32)), CHECK((active_credential_version IS NULL AND active_ref_digest IS NULL) OR (active_credential_version > 0 AND length(active_ref_digest) = 32)));
CREATE TRIGGER provider_credential_qualified_release_tuple_insert BEFORE INSERT ON provider_credential_operations WHEN NEW.qualified_release_tuple_digest IS NULL OR length(NEW.qualified_release_tuple_digest) != 32 OR NEW.qualified_release_tuple_digest = zeroblob(32) BEGIN SELECT RAISE(ABORT, 'credential qualified release tuple is required'); END;
CREATE TRIGGER provider_credential_qualified_release_tuple_immutable BEFORE UPDATE ON provider_credential_operations WHEN NEW.qualified_release_tuple_digest IS NOT OLD.qualified_release_tuple_digest BEGIN SELECT RAISE(ABORT, 'credential qualified release tuple is immutable'); END;
CREATE TRIGGER provider_credential_completion_receipt_insert BEFORE INSERT ON provider_credential_completion_receipts WHEN NOT EXISTS (SELECT 1 FROM provider_credential_operations AS operation JOIN provider_credential_authority_heads AS head ON head.provider_id = operation.provider_id WHERE operation.operation_id = NEW.operation_id AND operation.state = 'READBACK_VERIFIED' AND operation.installation_owner_id = NEW.installation_owner_id AND operation.provider_id = NEW.provider_id AND operation.action = NEW.action AND COALESCE(operation.allocated_credential_version, operation.target_credential_version) IS NEW.target_credential_version AND COALESCE(operation.allocated_ref_digest, operation.target_ref_digest) IS NEW.target_ref_digest AND operation.expected_lifecycle_revision = NEW.predecessor_lifecycle_revision AND operation.expected_credential_fence = NEW.predecessor_credential_fence AND operation.claimed_ticket_attempt = NEW.claimed_ticket_attempt AND operation.broker_migration_binding_digest IS NEW.broker_migration_binding_digest AND operation.qualified_release_tuple_digest = NEW.qualified_release_tuple_digest AND operation.readback_observation_digest = NEW.readback_observation_digest AND head.lifecycle_revision = NEW.successor_lifecycle_revision AND head.credential_fence = NEW.successor_credential_fence AND head.readiness_revision = NEW.successor_readiness_revision AND head.active_credential_version IS NEW.active_credential_version AND head.active_ref_digest IS NEW.active_ref_digest AND head.next_credential_version = NEW.next_credential_version) OR (NEW.action = 'LEGACY_SOURCE_CLEANUP' AND (NEW.readiness_observation_id IS NOT NULL OR NEW.successor_lifecycle_revision != NEW.predecessor_lifecycle_revision OR NEW.successor_credential_fence != NEW.predecessor_credential_fence)) OR (NEW.action != 'LEGACY_SOURCE_CLEANUP' AND (NEW.readiness_observation_id IS NULL OR NEW.successor_lifecycle_revision != NEW.predecessor_lifecycle_revision + 1 OR NEW.successor_credential_fence != NEW.predecessor_credential_fence + 1)) OR (NEW.action IN ('PAIR', 'MIGRATE_LEGACY') AND NEW.readback_disposition != 'EXACT_VERSION') OR (NEW.action IN ('REVOKE', 'RETIRED_VERSION_CLEANUP', 'LEGACY_SOURCE_CLEANUP') AND NEW.readback_disposition != 'EXACT_ABSENCE') BEGIN SELECT RAISE(ABORT, 'credential completion receipt does not match the authoritative completion'); END;
CREATE TRIGGER provider_credential_completion_receipt_append_only BEFORE UPDATE ON provider_credential_completion_receipts BEGIN SELECT RAISE(ABORT, 'credential completion receipt is append only'); END;
CREATE TRIGGER provider_credential_completion_receipt_no_delete BEFORE DELETE ON provider_credential_completion_receipts BEGIN SELECT RAISE(ABORT, 'credential completion receipt is append only'); END;
"#;

pub(super) fn apply_v28_migration(conn: &Connection) -> SqliteResult<()> {
    let transaction = Transaction::new_unchecked(conn, TransactionBehavior::Exclusive)?;
    transaction.execute_batch(MIGRATION_V28)?;
    install_missing_v12_fence_triggers(&transaction)?;
    transaction.execute("INSERT INTO schema_version (version) VALUES (28)", [])?;
    transaction.commit()
}
